/// Flat map from display name → WikiArt slug (used for API lookups).
let WikiArtStyleSlugMap: [String: String] = {
    var map: [String: String] = [:]
    for group in WikiArtStyleGroups {
        for style in group.styles {
            map[style.name] = style.slug
        }
    }
    return map
}()

